Clone() throws Exception {
        final Map<String, String> map = new HashMap<String, String>();
        map.put("key1", "value1");
        map.put("key2", "value2");
        final Serializable obj = new Serializable() {
            private static final long serialVersionUID = 1L;

            @Override
            public String toString() {
                return "obj";
            }
        };
        final Serializable clone = SerializationUtils.clone(obj);
        assertThat(clone, is(instanceOf(Serializable.class)));
        assertThat(clone, is(not(sameInstance(obj))));
        assertThat(clone, is(map));
    }

